  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Direct human evidence: nitrofurantoin, the query molecule, has approximately 90% oral bioavailability, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Absolute bioavailability estimates in humans, based on urinary recovery after IV and IM administration, indicate essentially complete absorption of nitrofurantoin from tablet and capsule formulations.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Benznidazole, a related nitroheterocycle, has >90% oral bioavailability in humans, supporting high bioavailability for this compound class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "5-Nitroimidazoles are almost completely and promptly absorbed with >90% bioavailability in humans, providing class-level support for high oral bioavailability of nitroheterocycles.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Azimilide, a hydantoin-furan derivative, has good oral bioavailability in humans, supporting the feasibility of high F for the query's hydantoin-nitrofuran scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Niridazole, a nitrothiazole, has low systemic availability due to high hepatic extraction; this is a counterexample within nitroheterocycles but has limited structural similarity to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Direct human data for nitrofurantoin report approximately 90% oral bioavailability and essentially complete absorption, decisively supporting F >= 20%. Additional high-bioavailability nitroheterocycles and a hydantoin-furan analogue reinforce this conclusion. The single low-bioavailability nitrothiazole (niridazole) is outweighed by the direct and class-level evidence.",
  "evidence_gaps": [
    "No explicit absolute bioavailability study with IV comparator for nitrofurantoin is cited; C05 uses urinary recovery after IV/IM and C06 has an unspecified report type.",
    "Some evidence records have SMILES that do not match the drug named in the reported text, creating uncertainty in record-to-structure mapping.",
    "No data on the query's metabolic stability or transporter effects are provided, though direct F data make these less critical."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

